package typesafe

import (
	"context"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// RetryPolicy bounds the retries of a 429 or 529. The wait before retry n is
// Base*2^n up to Cap, or the reply's retry-after when it has one. A wait over
// MaxWait is not slept: the error is returned instead of stalling the caller.
type RetryPolicy struct {
	Max     int // retries after the first attempt
	Base    time.Duration
	Cap     time.Duration
	MaxWait time.Duration
}

// DefaultRetryPolicy is five attempts, one to eight seconds apart.
var DefaultRetryPolicy = RetryPolicy{Max: 4, Base: time.Second, Cap: 8 * time.Second, MaxWait: time.Minute}

func (p RetryPolicy) backoff(retry int) time.Duration {
	d := p.Base
	for i := 0; i < retry && d < p.Cap; i++ {
		d *= 2
	}
	if d > p.Cap {
		d = p.Cap
	}
	return d
}

// wait is how long to sleep before retry number retry (from zero).
func (p RetryPolicy) wait(retry int, e *APIError) time.Duration {
	if e.RetryAfter > 0 {
		return e.RetryAfter
	}
	return p.backoff(retry)
}

// parseRetryAfter reads delta-seconds or an HTTP date; anything else is zero.
func parseRetryAfter(h http.Header, now time.Time) time.Duration {
	v := strings.TrimSpace(h.Get("Retry-After"))
	if v == "" {
		return 0
	}
	if secs, err := strconv.Atoi(v); err == nil {
		if secs < 0 {
			return 0
		}
		return time.Duration(secs) * time.Second
	}
	if t, err := http.ParseTime(v); err == nil {
		if d := t.Sub(now); d > 0 {
			return d
		}
	}
	return 0
}

func sleepCtx(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-t.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

package typesafe

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

// APIError is a non-200 reply. Detail names what the API objected to; for a
// 422 it lists every offending field path.
type APIError struct {
	Status     int
	Detail     string
	RetryAfter time.Duration // zero when the reply carried none
}

func (e *APIError) Error() string {
	if e.Detail == "" {
		return fmt.Sprintf("typesafe: HTTP %d", e.Status)
	}
	return fmt.Sprintf("typesafe: HTTP %d: %s", e.Status, e.Detail)
}

// retryable is the API's own list: rate limited or overloaded.
func (e *APIError) retryable() bool { return e.Status == 429 || e.Status == 529 }

// errorDetail renders the body of an error reply. It handles the three shapes
// the spec gives (a string, an object, a list of located validation errors)
// and falls back to the raw text, never to nothing.
func errorDetail(body []byte) string {
	var env struct {
		Detail json.RawMessage `json:"detail"`
	}
	if json.Unmarshal(body, &env) != nil || len(env.Detail) == 0 {
		return strings.TrimSpace(string(body))
	}
	var s string
	if json.Unmarshal(env.Detail, &s) == nil {
		return s
	}
	var fields []struct {
		Loc  []any  `json:"loc"`
		Msg  string `json:"msg"`
		Type string `json:"type"`
	}
	if json.Unmarshal(env.Detail, &fields) == nil && len(fields) > 0 {
		parts := make([]string, 0, len(fields))
		for _, f := range fields {
			loc := make([]string, len(f.Loc))
			for i, l := range f.Loc {
				loc[i] = fmt.Sprint(l)
			}
			parts = append(parts, fmt.Sprintf("%s: %s (%s)", strings.Join(loc, "."), f.Msg, f.Type))
		}
		return strings.Join(parts, "; ")
	}
	return string(env.Detail)
}

